##' convert a plot to grob object
##'
##'
##' @title as.grob
##' @rdname as-grob
##' @param plot base or grid plot, or graphic object generated by ggplot, lattice, etc.
##' A plot recorded by `grDevices::recordPlot()` is also accepted.
##' @param ... additional parameter, mostly will be ignored.
##' @details A `recordedplot` object holds the display list of the device that
##' drew the plot, so the display list must be enabled, via
##' `grDevices::dev.control(displaylist = "enable")`, before the plot is drawn.
##' A recording that holds no graphics, which is what an inhibited device
##' produces, cannot be converted and is reported as an error. Replaying a
##' recording also requires the same R version, graphics device and packages
##' that produced it, and is only guaranteed within the R session where
##' `recordPlot()` was called.
##'
##' A formula or an expression is evaluated in the environment that
##' `as.grob()` itself was called from, which is the global environment at the
##' top level. A variable that is local to the function calling `as.grob()` is
##' not visible there and needs `envir`, as in
##' `as.grob(~barplot(n), envir = environment())`.
##' @return grob object
##' @export
##' @examples
##' as.grob(~barplot(1:10))
##'
##' grDevices::pdf(tempfile(fileext = ".pdf"))
##' grDevices::dev.control(displaylist = "enable")
##' plot(1:10, type = "b")
##' rec <- grDevices::recordPlot()
##' grDevices::dev.off()
##'
##' g <- as.grob(rec)
##' @author Guangchuang Yu
as.grob <- function(plot, ...) {
    UseMethod("as.grob")
}

##' @rdname as-grob
##' @method as.grob aplot
##' @export
as.grob.aplot <- function(plot, ...) {
    aplotGrob <- utils::getFromNamespace("aplotGrob", "aplot")
    aplotGrob(plot)
}

##' @rdname as-grob
##' @method as.grob oncoplot
##' @export
as.grob.oncoplot <- function(plot, ...) {
    oncoplotGrob <- utils::getFromNamespace("oncoplotGrob", "aplot")
    oncoplotGrob(plot)
}

##' @rdname as-grob
##' @method as.grob bbplot
##' @export
as.grob.bbplot <- function(plot, ...) {
    base2grob(~print(plot))
}

##' @rdname as-grob
##' @method as.grob patchwork
##' @export
as.grob.patchwork <- function(plot, ...) {
    patchworkGrob <- utils::getFromNamespace("patchworkGrob", "patchwork")
    patchworkGrob(plot)
}

##' @rdname as-grob
##' @method as.grob gglist
##' @export
as.grob.gglist <- function(plot, ...) {
    gglistGrob <- utils::getFromNamespace("gglistGrob", "aplot")
    gglistGrob(plot)
}

##' @rdname as-grob
##' @method as.grob expression
##' @export
as.grob.expression <- function(plot, ...) {
    p <- tryCatch(base2grob(plot, ...),
                  error = function(e) NULL)

    if (is.null(p)) {
        p <- grid2grob(plot_fun(plot, ...)())
    }

    return(p)
}

##' @rdname as-grob
##' @method as.grob formula
##' @export
as.grob.formula <- as.grob.expression


##' @rdname as-grob
##' @method as.grob function
##' @export
as.grob.function <- as.grob.expression

##' @rdname as-grob
##' @importFrom ggplot2 ggplotGrob
##' @method as.grob ggplot
##' @export
as.grob.ggplot <- function(plot, ...) {
    ggplotGrob(plot)
}

##' @rdname as-grob
##' @importFrom yulab.utils get_fun_from_pkg
##' @method as.grob meme
##' @export
as.grob.meme <- function(plot, ...) {
    memeGrob <- get_fun_from_pkg("meme", "memeGrob")
    memeGrob(plot)
